tests.setup:
const { prisma } = await app("lib/prisma.ts");
const { toggleVoteAction, createFeedbackAction } = await app("lib/actions/feedback.ts");
const { requireUser } = await app("lib/workspace.ts");

// Create a user
const user = await prisma.user.create({ data: { email: "user@example.com", name: "Test User", passwordHash: "hash" } });

// Create a workspace
const workspace = await prisma.workspace.create({ data: { name: "Test Workspace", slug: "test-workspace", webhookSecret: "secret" } });

// Add membership for user in workspace
await prisma.membership.create({ data: { userId: user.id, workspaceId: workspace.id, role: "MEMBER" } });

// Create a feedback item in the workspace
const feedback = await prisma.feedback.create({ data: { title: "Test Feedback", body: "This is a test feedback.", workspaceId: workspace.id, authorId: user.id } });

// Set session for the user
set_session({ user: { id: user.id, email: user.email, name: user.name } });

tests.body:
arranged();

// Run two toggleVoteAction calls concurrently without waiting for the first to finish
const p1 = toggleVoteAction(workspace.slug, feedback.id);
const p2 = toggleVoteAction(workspace.slug, feedback.id);

let err1 = null;
let err2 = null;

try {
  await p1;
} catch (e) {
  err1 = e;
}
try {
  await p2;
} catch (e) {
  err2 = e;
}

record("error1", err1 ? String(err1.message) : null);
record("error2", err2 ? String(err2.message) : null);

// Count votes for the feedback
const voteCount = await prisma.vote.count({ where: { feedbackId: feedback.id } });
record("voteCount", voteCount);

// Harm observed if either call threw a unique constraint violation error
const harmObserved = (err1 && err1.message.includes("Unique constraint failed")) || (err2 && err2.message.includes("Unique constraint failed"));
harm_observed(harmObserved, "Unique constraint violation occurred due to concurrent vote toggles");

arranged();

// Initially no votes
let count = await prisma.vote.count({ where: { feedbackId: feedback.id } });
check(count === 0, "No votes initially");

// Add vote
await toggleVoteAction(workspace.slug, feedback.id);
count = await prisma.vote.count({ where: { feedbackId: feedback.id } });
check(count === 1, "One vote after adding");

// Remove vote
await toggleVoteAction(workspace.slug, feedback.id);
count = await prisma.vote.count({ where: { feedbackId: feedback.id } });
check(count === 0, "No votes after removing");

arranged();

// Count votes before toggling
const initialCount = await prisma.vote.count({ where: { feedbackId: feedback.id } });

// Call toggleVoteAction once
await toggleVoteAction(workspace.slug, feedback.id);

// Count votes after toggling
const afterToggleCount = await prisma.vote.count({ where: { feedbackId: feedback.id } });

// The vote count should have changed by exactly 1 (either added or removed)
check(
  afterToggleCount === initialCount + 1 || afterToggleCount === initialCount - 1,
  `Vote count changed by 1 after toggle: before=${initialCount}, after=${afterToggleCount}`
);

